/*! Bootstrap v5.1.3 | (c) 2011-2021 Twitter, Inc. | https://github.com/twbs/bootstrap */
/* Simplified Bootstrap JS for local use */

(function() {
    'use strict';
    
    // Basic Modal functionality
    window.Bootstrap = {
        Modal: function(element, options) {
            this.element = element;
            this.options = options || {};
            
            this.show = function() {
                this.element.style.display = 'block';
                this.element.classList.add('show');
                document.body.classList.add('modal-open');
            };
            
            this.hide = function() {
                this.element.style.display = 'none';
                this.element.classList.remove('show');
                document.body.classList.remove('modal-open');
            };
            
            // Close on backdrop click
            this.element.addEventListener('click', function(e) {
                if (e.target === this) {
                    this.hide();
                }
            }.bind(this));
        },
        
        // Basic Alert functionality
        Alert: function(element) {
            this.element = element;
            
            this.close = function() {
                this.element.style.display = 'none';
            };
        },
        
        // Basic Dropdown functionality
        Dropdown: function(element) {
            this.element = element;
            this.menu = element.nextElementSibling;
            
            this.toggle = function() {
                if (this.menu.classList.contains('show')) {
                    this.menu.classList.remove('show');
                } else {
                    this.menu.classList.add('show');
                }
            };
            
            this.element.addEventListener('click', this.toggle.bind(this));
        }
    };
    
    // Auto-initialize components
    document.addEventListener('DOMContentLoaded', function() {
        // Initialize modals
        var modals = document.querySelectorAll('[data-bs-toggle="modal"]');
        modals.forEach(function(trigger) {
            trigger.addEventListener('click', function() {
                var target = document.querySelector(this.getAttribute('data-bs-target'));
                if (target) {
                    var modal = new Bootstrap.Modal(target);
                    modal.show();
                }
            });
        });
        
        // Initialize alerts
        var alerts = document.querySelectorAll('[data-bs-dismiss="alert"]');
        alerts.forEach(function(trigger) {
            trigger.addEventListener('click', function() {
                var alert = this.closest('.alert');
                if (alert) {
                    var alertInstance = new Bootstrap.Alert(alert);
                    alertInstance.close();
                }
            });
        });
        
        // Initialize dropdowns
        var dropdowns = document.querySelectorAll('[data-bs-toggle="dropdown"]');
        dropdowns.forEach(function(trigger) {
            new Bootstrap.Dropdown(trigger);
        });
    });
})();
